<template><div class="page"><h2 class="page-title">今天的财务状态</h2><p class="muted">只展示已保存的真实业务数据；缺失项不会用示例数代替。</p><div v-loading="loading" class="grid section"><div class="card"><span class="muted">当前存款</span><div class="metric">{{ formatMoney(data.current_savings_minor) }}</div></div><div class="card"><span class="muted">本月实际消费</span><div class="metric">{{ formatMoney(data.monthly_actual_minor) }}</div></div><div class="card"><span class="muted">储蓄目标</span><div class="metric">{{ formatMoney(data.goal?.target_savings_minor) }}</div></div><div class="card"><span class="muted">情景风险</span><div class="metric">{{ data.plan?.risk_level || '暂无数据' }}</div><small>不是成功概率</small></div></div><div class="card section"><h3>最近周度净消费</h3><EChart v-if="data.recent_weekly?.length" :option="chart"/><EmptyGuide v-else description="尚无消费数据，请先导入微信账单" action="/bills"/></div></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue'
const data=ref({}),loading=ref(true);onMounted(async()=>{try{data.value=await api.get('/dashboard')}finally{loading.value=false}})
const chart=computed(()=>({tooltip:{trigger:'axis',valueFormatter:v=>formatMoney(v)},xAxis:{type:'category',data:(data.value.recent_weekly||[]).map(x=>x.week_start)},yAxis:{type:'value'},series:[{type:'line',smooth:true,areaStyle:{opacity:.12},data:(data.value.recent_weekly||[]).map(x=>x.net_consumption_minor),color:'#2b9a72'}]}))
</script>
